using System;using Newtonsoft.Json.Linq;using Game.UI.Contracts;using Game.UI.Runtime;namespace Game.Runtime{internal static class SourceCatalogRowsWire{internal static JObject Read(SourceCatalogRows source,BuildDrawerCategory category,CatalogPublicFacts facts){var rows=new JArray();foreach(var x in source.Read(category,facts))rows.Add(new JObject{["category"]=x.Category.ToString(),["prefab"]=new JObject{["identity"]=x.Prefab.Identity,["name"]=x.Prefab.name},["display_name"]=x.DisplayName,["type_label"]=x.TypeLabel,["description"]=x.Description,["credits_cost"]=x.CreditsCost,["materials_cost"]=x.MaterialsCost,["fuel_cost"]=x.FuelCost,["production_duration_seconds"]=x.ProductionDurationSeconds,["footprint_cells"]=new JObject{["x"]=x.FootprintCells.x,["y"]=x.FootprintCells.y},["portrait_identity"]=x.Portrait?.Identity,["card_portrait_identity"]=x.CardPortrait?.Identity,["action_portrait_identity"]=x.ActionPortrait?.Identity});return new JObject{["qualification"]="SOURCE_ENUMERATED_CATALOG_ROWS",["category"]=category.ToString(),["rows"]=rows,["membership_known"]=true,["availability"]=new JObject{["known"]=false,["required_source"]="current GetCampRequestFailure, CanInspectUnavailable and original command binding/primary callback"},["native_ui_binding"]="UNKNOWN"};}}}